function formatTinyDecimal(value: number) {
  if (value > 0 && value < 0.01) return "< 0.01";
  if (value < 0 && value > -0.01) return "> -0.01";
  return null;
}

function formatCurrency(value: unknown) {
  if (value === undefined || value === null || value === "") return "-";
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return "-";
  const tinyValue = formatTinyDecimal(numeric);
  if (tinyValue) return tinyValue;
  const sign = numeric < 0 ? "-" : "";
  const abs = Math.abs(numeric);
  const format = (next: number) => {
    const truncated = Math.floor(next * 100) / 100;
    return truncated.toLocaleString(undefined, {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
  };
  const formatAbbreviated = (next: number) => {
    const truncated = Math.floor(next * 10) / 10;
    return truncated.toLocaleString(undefined, {
      minimumFractionDigits: 1,
      maximumFractionDigits: 1,
    });
  };

  if (abs >= 1_000_000_000) {
    return `${sign}$${formatAbbreviated(abs / 1_000_000_000)}B`;
  }
  if (abs >= 1_000_000) {
    return `${sign}$${formatAbbreviated(abs / 1_000_000)}M`;
  }
  if (abs >= 1_000) return `${sign}$${formatAbbreviated(abs / 1_000)}K`;
  if (abs >= 1) return `${sign}$${Math.floor(abs).toLocaleString()}`;
  return `${sign}$${format(abs)}`;
}

function formatInteger(value: unknown) {
  if (value === undefined || value === null || value === "") return "-";
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return "-";
  return new Intl.NumberFormat(undefined, { maximumFractionDigits: 0 }).format(
    Math.floor(numeric)
  );
}

function formatCompactCurrency(value: unknown) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return "-";
  const tinyValue = formatTinyDecimal(numeric);
  if (tinyValue) return tinyValue;
  const abs = Math.abs(numeric);
  const sign = numeric < 0 ? "-" : "";
  const format = (next: number) => {
    const truncated = Math.floor(next * 100) / 100;
    return truncated.toLocaleString(undefined, {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
  };

  if (abs >= 1_000_000_000) return `${sign}$${format(abs / 1_000_000_000)}B`;
  if (abs >= 1_000_000) return `${sign}$${format(abs / 1_000_000)}M`;
  if (abs >= 1_000) return `${sign}$${format(abs / 1_000)}K`;
  if (abs >= 1) return `${sign}$${Math.floor(abs).toLocaleString()}`;
  return `${sign}$${format(abs)}`;
}

function formatCompactCurrencyAxis(value: unknown) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return "-";
  if (numeric === 0) return "0.00";
  if (numeric > -0.01 && numeric < 0.01) return "";
  const abs = Math.abs(numeric);
  const sign = numeric < 0 ? "-" : "";
  const format = (next: number) =>
    next.toLocaleString(undefined, {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
  const formatAbbreviated = (next: number) =>
    next.toLocaleString(undefined, {
      minimumFractionDigits: 1,
      maximumFractionDigits: 1,
    });

  if (abs >= 1_000_000_000) {
    return `${sign}$${formatAbbreviated(abs / 1_000_000_000)}B`;
  }
  if (abs >= 1_000_000) {
    return `${sign}$${formatAbbreviated(abs / 1_000_000)}M`;
  }
  if (abs >= 1_000) return `${sign}$${formatAbbreviated(abs / 1_000)}K`;
  if (abs >= 1) return `${sign}$${Math.floor(abs).toLocaleString()}`;
  return `${sign}$${format(abs)}`;
}

function getCurrencyAxisTicks(data: TrendPoint[]) {
  const values = data
    .map(point => Number(point.value))
    .filter(value => Number.isFinite(value));
  if (!values.length) return undefined;

  const minValue = Math.min(0, ...values);
  const maxValue = Math.max(0, ...values);
  const range = maxValue - minValue;

  const maxAbs = Math.max(Math.abs(minValue), Math.abs(maxValue), range);

  if (maxAbs >= 1_000) {
    return undefined;
  }

  if (maxAbs >= 1) {
    const step = Math.max(1, Math.ceil(range / 4));
    const minTick = Math.floor(minValue / step) * step;
    const maxTick = Math.ceil(maxValue / step) * step;
    const ticks: number[] = [];

    for (let tick = minTick; tick <= maxTick; tick += step) {
      ticks.push(tick);
    }

    if (!ticks.includes(0)) {
      ticks.push(0);
      ticks.sort((left, right) => left - right);
    }

    return ticks;
  }

  const step = Math.max(0.01, Math.ceil((range / 4) * 100) / 100);
  const minTick = Math.floor(minValue / step) * step;
  const maxTick = Math.ceil(maxValue / step) * step;
  const ticks: number[] = [];

  for (let tick = minTick; tick <= maxTick + step / 2; tick += step) {
    ticks.push(Number(tick.toFixed(2)));
  }

  if (!ticks.includes(0)) {
    ticks.push(0);
    ticks.sort((left, right) => left - right);
  }

  return ticks;
}

function getIntegerAxisTicks(data: TrendPoint[]) {
  const values = data
    .map(point => Number(point.value))
    .filter(value => Number.isFinite(value));
  if (!values.length) return undefined;

  const minValue = Math.min(0, ...values);
  const maxValue = Math.max(0, ...values);
  const range = maxValue - minValue;
  const step = Math.max(1, Math.ceil(range / 4));
  const minTick = Math.floor(minValue / step) * step;
  const maxTick = Math.ceil(maxValue / step) * step;
  const ticks: number[] = [];

  for (let tick = minTick; tick <= maxTick; tick += step) {
    ticks.push(tick);
  }

  if (!ticks.includes(0)) {
    ticks.push(0);
    ticks.sort((left, right) => left - right);
  }

  return ticks;
}

function firstFiniteNumber(...values: unknown[]) {
  for (const value of values) {
    const numeric = Number(value);
    if (Number.isFinite(numeric)) return numeric;
  }
  return undefined;
}

function firstFiniteRowNumber(row: Record<string, unknown>, keys: string[]) {
  for (const key of keys) {
    const numeric = Number(row[key]);
    if (Number.isFinite(numeric)) return numeric;
  }
  return undefined;
}

function formatPercentChange(
  current: unknown,
  previous: unknown,
  label: string,
  t?: TranslationFn
) {
  const currentValue = Number(current);
  const previousValue = Number(previous);

  if (!Number.isFinite(currentValue) || !Number.isFinite(previousValue)) {
    return { text: "", tone: "muted" as MetricTone };
  }

  if (previousValue === 0) {
    if (currentValue === 0) {
      return {
        text: t
          ? t("dataAnalytics.dashboard.changeVs", {
              change: "0.00%",
              label,
            })
          : `0.00% vs ${label}`,
        tone: "muted" as MetricTone,
      };
    }
    return {
      text: t
        ? t("dataAnalytics.dashboard.newVs", { label })
        : `New vs ${label}`,
      tone: "positive" as MetricTone,
    };
  }

  const change =
    ((currentValue - previousValue) / Math.abs(previousValue)) * 100;
  const sign = change > 0 ? "+" : change < 0 ? "-" : "";
  const tone: MetricTone =
    change > 0 ? "positive" : change < 0 ? "negative" : "muted";
  const truncated = Math.floor(Math.abs(change) * 100) / 100;
  const changeLabel = `${sign}${truncated.toFixed(2)}%`;
  return {
    text: t
      ? t("dataAnalytics.dashboard.changeVs", {
          change: changeLabel,
          label,
        })
      : `${changeLabel} vs ${label}`,
    tone,
  };
}

function formatPercentValue(value: unknown) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric))
    return { text: "-", tone: "muted" as MetricTone };
  const sign = numeric > 0 ? "+" : numeric < 0 ? "-" : "";
  const tone: MetricTone =
    numeric > 0 ? "positive" : numeric < 0 ? "negative" : "muted";
  const truncated = Math.floor(Math.abs(numeric) * 100) / 100;
  return { text: `${sign}${truncated.toFixed(2)}%`, tone };
}

function formatTrendDate(value: unknown) {
  const date = parseUtcDateKey(String(value || "").slice(0, 10));
  if (!date) return String(value || "");
  return date.toLocaleDateString(undefined, {
    month: "short",
    day: "numeric",
    timeZone: "UTC",
  });
}

function normalizeBrokerId(value: unknown) {
  return typeof value === "string" ? value.trim().toLowerCase() : "";
}

function getMatchingUserMetricRow(rows: DexUserMetricRow[], brokerId: string) {
  const normalizedBrokerId = normalizeBrokerId(brokerId);
  if (!normalizedBrokerId) return null;
  return (
    rows.find(row => normalizeBrokerId(row.broker_id) === normalizedBrokerId) ||
    null
  );
}

