function getDateKey(row: BuilderDailyStatsRow) {
  const value = row.dateString || row.date;
  if (typeof value !== "string") return "";
  const parsed = parseUtcDateKey(value.slice(0, 10));
  return parsed ? formatUtcDateKey(parsed) : value.slice(0, 10);
}

function getFundFlowDateKey(row: FundFlowRow) {
  return typeof row.date === "string" ? row.date.slice(0, 10) : "";
}

function parseUtcDateKey(value: string) {
  const [year, month, day] = value.split("-").map(Number);
  if (!year || !month || !day) return null;
  return new Date(Date.UTC(year, month - 1, day));
}

function formatUtcDateKey(date: Date) {
  return date.toISOString().slice(0, 10);
}

function addUtcDays(date: Date, days: number) {
  return new Date(date.getTime() + days * DAY_MS);
}

function getCurrentUtcDate() {
  const now = new Date();
  return new Date(
    Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate())
  );
}

function sortDailyRows(rows: BuilderDailyStatsRow[]) {
  return [...rows].sort((left, right) => {
    const leftTime = parseUtcDateKey(getDateKey(left))?.getTime() ?? 0;
    const rightTime = parseUtcDateKey(getDateKey(right))?.getTime() ?? 0;
    return leftTime - rightTime;
  });
}

function getDailyVolume(row: BuilderDailyStatsRow | null | undefined) {
  if (!row) return undefined;
  const takerVolume = firstFiniteNumber(row.takerVolume) ?? 0;
  const makerVolume = firstFiniteNumber(row.makerVolume) ?? 0;
  const total = takerVolume + makerVolume;
  if (total > 0) return total;
  return firstFiniteNumber(row.perp_volume, row.volume);
}

function getDailyRowForDate(rows: BuilderDailyStatsRow[], dateKey: string) {
  return rows.find(row => getDateKey(row) === dateKey) || null;
}

function sumFiniteRows(
  rows: BuilderDailyStatsRow[],
  getValue: (row: BuilderDailyStatsRow) => unknown
) {
  let count = 0;
  const sum = rows.reduce((total, row) => {
    const value = Number(getValue(row));
    if (!Number.isFinite(value)) return total;
    count += 1;
    return total + value;
  }, 0);
  return count ? sum : undefined;
}

function getBuilderVolumeTrend(rows: BuilderDailyStatsRow[]): TrendPoint[] {
  return sortDailyRows(rows)
    .slice(-BUILDER_ANALYTICS_MAX_RANGE)
    .map(row => ({ date: getDateKey(row), value: getDailyVolume(row) }))
    .filter(point => point.date);
}

function getActiveTradersTrend(rows: BuilderDailyStatsRow[]): TrendPoint[] {
  return sortDailyRows(rows)
    .slice(-BUILDER_ANALYTICS_MAX_RANGE)
    .map(row => ({
      date: getDateKey(row),
      value: firstFiniteNumber(row.activeUser),
    }))
    .filter(point => point.date);
}

function getDailyNetflowTrend(
  rows: FundFlowRow[],
  brokerId: string
): TrendPoint[] {
  const normalizedBrokerId = normalizeBrokerId(brokerId);
  if (!normalizedBrokerId) return [];

  const totalsByDate = new Map<string, number>();
  rows.forEach(row => {
    if (normalizeBrokerId(row.broker_id) !== normalizedBrokerId) return;
    const date = getFundFlowDateKey(row);
    if (!date) return;
    const netFlow = firstFiniteNumber(
      row.net_flow_usd,
      Number(row.deposits_usd || 0) - Number(row.withdrawals_usd || 0)
    );
    if (netFlow === undefined) return;
    totalsByDate.set(date, (totalsByDate.get(date) || 0) + netFlow);
  });

  return [...totalsByDate.entries()]
    .sort(([leftDate], [rightDate]) => leftDate.localeCompare(rightDate))
    .slice(-BUILDER_ANALYTICS_MAX_RANGE)
    .map(([date, value]) => ({ date, value }));
}

function fillDailyTrendRange(
  data: TrendPoint[],
  startDate: Date,
  endDate: Date
): TrendPoint[] {
  const valuesByDate = new Map<string, number>();
  data.forEach(point => {
    const date = parseUtcDateKey(point.date);
    if (!date) return;
    const value = Number(point.value);
    valuesByDate.set(
      formatUtcDateKey(date),
      Number.isFinite(value) ? value : 0
    );
  });

  const points: TrendPoint[] = [];
  for (
    let date = startDate;
    date.getTime() <= endDate.getTime();
    date = addUtcDays(date, 1)
  ) {
    const key = formatUtcDateKey(date);
    points.push({ date: key, value: valuesByDate.get(key) ?? 0 });
  }

  return points;
}

function getTrendRangeData(data: TrendPoint[], range: BuilderAnalyticsRange) {
  return data.slice(-range);
}

